Assert-Contains "editor owns draft repository" $scenarioDraftRepository 'class ScenarioAuthoringDraftRepository.*DraftStorageScenarioId\s*=\s*"ScenarioAuthoringDrafts".*CreateDraft\(ScenarioBaseGameMode baseMode\).*ListAll\(' "draft creation and discovery must stay inside ShelteredScenarioEditor."
