# Typed-only command lane: presentation constructs commands, exactly one registered
# handler owns each command type, and command shape/routing policy has one catalog.
Assert-Contains "typed story command lane" ($scenarioQuestAuthoringContentBuilder + $typedStoryAuthoringCommandHandler) 'StoryAuthoringCommands\..*TypedStoryAuthoringCommandHandler\s*:\s*IScenarioCommandHandler.*command as StoryAuthoringCommand.*TryHandleCommand' "Story presentation and mutation must share the typed Story command lane."
Assert-Contains "single command owner" $scenarioCommandDispatcher '_handlerByCommandType.*FindSoleHandler\(command\).*Multiple scenario command handlers own' "dispatch must cache and enforce exactly one handler owner per concrete command type."
Assert-Contains "authoritative dispatch outcome" $scenarioCommandDispatcher 'internal struct ScenarioCommandDispatchResult.*bool Handled.*bool Changed.*string Message' "dispatch outcomes must use the allocation-free result value with Changed as the mutation authority."
Assert-NotContains "authoritative dispatch outcome" $scenarioCommandDispatcher 'public bool Result|handler\.Handle\(state, command\)\s*\?\?' "dispatch outcomes must not retain the redundant Result alias or impossible null-result fallback."
Assert-Contains "story descriptor source of truth" ($storyAuthoringCommand + $scenarioStoryAuthoringTypedService) 'StoryAuthoringCommandCatalog\.Describe\(Kind\).*descriptor\.Requires.*StoryAuthoringCommandCatalog\.Describe\(command\.Kind\)\.Family.*StoryAuthoringCommandCatalog\.Describe\(command\.Kind\)\.Group' "Story validation and mutation routing must consume the same per-kind descriptor catalog."
Assert-NotContains "story descriptor source of truth" ($storyAuthoringCommand + $scenarioStoryAuthoringTypedService) 'NeedsPrimary|NeedsSecondary|NeedsChild|NeedsDelta|NeedsValue|IsFlowCommand|IsCharacterCommand|IsConversationCommand|Enum\.GetName|kind\s*[<>]=' "Story command classification must not depend on duplicate helpers, enum names, or enum ordinal ranges."

$storyKindBody = [regex]::Match($storyAuthoringCommand, 'internal enum StoryAuthoringCommandKind\s*\{(?<body>.*?)\}', [Text.RegularExpressions.RegexOptions]::Singleline).Groups['body'].Value
$storyKinds = [regex]::Matches($storyKindBody, '\b([A-Za-z][A-Za-z0-9_]*)\b') | ForEach-Object { $_.Groups[1].Value }
$storyCatalogCases = [regex]::Matches($storyAuthoringCommandCatalog, 'case StoryAuthoringCommandKind\.([A-Za-z0-9_]+):') | ForEach-Object { $_.Groups[1].Value }
$storyKindDiff = @(Compare-Object $storyKinds $storyCatalogCases)
$duplicateStoryCatalogCases = @($storyCatalogCases | Group-Object | Where-Object { $_.Count -ne 1 })
if (@($storyKinds).Count -eq 0 -or $storyKindDiff.Count -gt 0 -or $duplicateStoryCatalogCases.Count -gt 0) {
    $failures.Add("story descriptor source of truth: every StoryAuthoringCommandKind must have exactly one descriptor case")
}

foreach ($removedLegacyStorySource in @(
    'ShelteredScenarioEditor\Application\Authoring\ScenarioStoryAuthoringActions.cs',
    'ShelteredScenarioEditor\Application\Authoring\ScenarioMetadataAuthoringActions.cs')) {
    if (Test-Path -LiteralPath (Join-Path $RepoRoot $removedLegacyStorySource)) {
        $failures.Add("typed-only command lane: removed legacy action parser still exists: $removedLegacyStorySource")
    }
}
